\begin{aligned}
 m_\chi
 &=\frac1{|\mathcal H|}
 \sum_{h\in\mathcal H}\overline{\chi(h)}\,\mathrm{tr}(h)\\
 &=\frac{D}{|\mathcal H|}
 \sum_{c\in\mathcal C}\overline{\chi(c)}\chi_0(c)\\
 &=
 \begin{cases}
 D|\mathcal C|/|\mathcal H|,
    &\chi|_{\mathcal C}=\chi_0,\\
 0,&\text{otherwise}.
 \end{cases}
\end{aligned}
 \tag{CB14}
